const source = $input.first().json;
const profile = source.output;

if (!profile || typeof profile !== 'object' || Array.isArray(profile)) {
  throw new Error('Candidate profile must be a JSON object');
}

const candidate =
  profile.candidate &&
  typeof profile.candidate === 'object' &&
  !Array.isArray(profile.candidate)
    ? profile.candidate
    : {};

const skills = Array.isArray(profile.skills)
  ? profile.skills
  : [];

const education = Array.isArray(profile.education)
  ? profile.education
  : [];

const workExperiences = Array.isArray(profile.workExperiences)
  ? profile.workExperiences
  : [];

const warnings = Array.isArray(profile.warnings)
  ? profile.warnings.map(String)
  : [];

const errors = [];

const fullName = String(candidate.fullName ?? '').trim();
const email = String(candidate.email ?? '').trim().toLowerCase();

if (profile.schemaVersion !== '1.0') {
  errors.push('Unsupported candidate profile schema version');
}

if (!fullName) {
  errors.push('Candidate full name is required');
}

if (
  email &&
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
) {
  errors.push('Candidate email format is invalid');
}

if (skills.length === 0) {
  errors.push('At least one evidenced skill is required');
}

const allowedConfidence = new Set([
  'HIGH',
  'MEDIUM',
  'LOW'
]);

const seenSkills = new Set();
const normalizedSkills = [];

for (const skill of skills) {
  const name = String(skill?.name ?? '').trim();
  const evidence = String(skill?.evidence ?? '').trim();
  const confidence = String(
    skill?.confidence ?? ''
  ).trim().toUpperCase();

  if (!name) {
    errors.push('Every skill must have a name');
    continue;
  }

  if (!evidence) {
    errors.push(`Skill '${name}' has no supporting evidence`);
  }

  if (!allowedConfidence.has(confidence)) {
    errors.push(`Skill '${name}' has invalid confidence`);
  }

  const key = name.toLowerCase();

  if (seenSkills.has(key)) {
    continue;
  }

  seenSkills.add(key);

  normalizedSkills.push({
    name,
    category: String(skill.category ?? 'OTHER')
      .trim()
      .toUpperCase(),
    claimedDuration: String(
      skill.claimedDuration ?? ''
    ).trim(),
    evidence,
    confidence
  });
}

if (errors.length > 0) {
  throw new Error(
    `Candidate profile validation failed: ${errors.join('; ')}`
  );
}

const intake = $('Validate Assessment Intake').first().json;

return [
  {
    json: {
      output: {
        schemaVersion: '1.0',
        candidate: {
          fullName,
          email,
          phone: String(candidate.phone ?? '').trim(),
          location: String(candidate.location ?? '').trim(),
          linkedInUrl: String(candidate.linkedInUrl ?? '').trim()
        },
        skills: normalizedSkills,
        education,
        workExperiences,
        warnings
      },
      validation: {
        valid: true,
        errors: []
      },
      metadata: {
        workflowExecutionId: String($execution.id),
        sourceFileName: intake.sourceFileName,
        positionCode: intake.positionCode,
        targetGradeCode: intake.targetGradeCode,
        jobDescription: intake.jobDescription,
        extractionModel: 'gpt-5.6-sol',
        profileSchemaVersion: '1.0',
        extractedAt: new Date().toISOString()
      }
    }
  }
];

const item = $input.first();

const positionCode = String(
  item.json.positionCode ?? ''
).trim().toUpperCase();

const targetGradeCode = String(
  item.json.targetGradeCode ?? ''
).trim().toUpperCase();

const jobDescription = String(
  item.json.jobDescription ?? ''
).trim();

const resume = item.binary?.resume;

const allowedGrades = new Set([
  'JUNIOR',
  'MID',
  'SENIOR'
]);

if (positionCode !== 'JAVA_BACKEND') {
  throw new Error(
    `Unsupported position code: ${positionCode || 'empty'}`
  );
}

if (!allowedGrades.has(targetGradeCode)) {
  throw new Error(
    `Unsupported target grade: ${targetGradeCode || 'empty'}`
  );
}

if (jobDescription.length < 30) {
  throw new Error(
    'Job description must contain at least 30 characters'
  );
}

if (!resume) {
  throw new Error(
    'A resume PDF file is required'
  );
}

const fileName = String(
  resume.fileName ?? ''
).trim();

const mimeType = String(
  resume.mimeType ?? ''
).trim().toLowerCase();

if (!fileName.toLowerCase().endsWith('.pdf')) {
  throw new Error(
    `Only PDF resumes are supported: ${fileName || 'unknown file'}`
  );
}

if (
  mimeType &&
  mimeType !== 'application/pdf' &&
  mimeType !== 'application/octet-stream'
) {
  throw new Error(
    `Unsupported resume MIME type: ${mimeType}`
  );
}

return [
  {
    json: {
      positionCode,
      targetGradeCode,
      jobDescription,
      sourceFileName: fileName,
      sourceMimeType: mimeType || 'application/pdf'
    },
    binary: item.binary
  }
];

